const ED = 'https://latex.giit.ch', ed = document.getElementById('ed');
addEventListener('message', e => {
  if (e.origin !== ED || e.source !== ed.contentWindow) return;
  const m = e.data;
  if (m.type === 'latexeditor:ready')
    ed.contentWindow.postMessage({ type: 'latexeditor:load', name: 'Offer', content: myText }, ED);
  if (m.type === 'latexeditor:change') markUnsaved();
  if (m.type === 'latexeditor:save') saveOnYourServer(m.content, m.assets);
});

ed.contentWindow.postMessage({ type: 'latexeditor:load', name: 'Offer', content: myText,
  ai: { label: 'My Admin', prompt: 'Keep the placeholders.',
        endpoint: 'https://your-site.com/api/ai-result', key: sessionKey } }, ED);
